(31,'service-ai-ugc-video-creation-company','Ai Ugc Video Creation Service','Referenced Organization','Organization','{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Organization\",\n    \"@id\": \"https://myugcvideo.in/#organization\",\n    \"name\": \"MY UGC VIDEO\",\n    \"url\": \"https://myugcvideo.in\",\n    \"logo\": {\n        \"@type\": \"ImageObject\",\n        \"@id\": \"https://myugcvideo.in/#logo\",\n        \"url\": \"https://myugcvideo.in/images/hero/hero-creator.jpg\",\n        \"caption\": \"MY UGC VIDEO Studio Logo\"\n    },\n    \"image\": \"https://myugcvideo.in/images/hero/hero-ugc-production.jpg\",\n    \"description\": \"Premier performance-driven UGC video production studio and creator network connecting brands with authentic creator-led video content.\",\n    \"email\": \"hello@myugcvideo.in\",\n    \"sameAs\": [\n        \"https://instagram.com\",\n        \"https://linkedin.com\"\n    ],\n    \"contactPoint\": [\n        {\n            \"@type\": \"ContactPoint\",\n            \"contactType\": \"customer service\",\n            \"email\": \"hello@myugcvideo.in\",\n            \"availableLanguage\": [\n                \"English\",\n                \"Hindi\"\n            ]\n        }\n    ],\n    \"areaServed\": [\n        {\n            \"@type\": \"Country\",\n            \"name\": \"India\"\n        }\n    ]\n}','published','2026-11-05 15:33:54','2026-11-13 14:14:39'),
(32,'service-ai-ugc-video-creation-company','Ai Ugc Video Creation Service','Ai Ugc Video Creation Service BreadcrumbList Schema','BreadcrumbList','{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"BreadcrumbList\",\n    \"@id\": \"https://myugcvideo.in/services/ai-ugc-video-creation-company#breadcrumb\",\n    \"itemListElement\": [\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 1,\n            \"name\": \"Home\",\n            \"item\": \"https://myugcvideo.in\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 2,\n            \"name\": \"Services\",\n            \"item\": \"https://myugcvideo.in/services\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 3,\n            \"name\": \"Ai Ugc Video Creation Service\",\n            \"item\": \"https://myugcvideo.in/services/ai-ugc-video-creation-company\"\n        }\n    ]\n}','published','2026-11-05 15:33:54','2026-11-13 14:14:39'),
(34,'service-ai-ugc-video-creation-company','Ai Ugc Video Creation Service','Ai Ugc Video Creation Service FAQPage Schema','FAQPage','{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ai-ugc-video-creation-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Does AI UGC video creation look natural to social media users?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Mostly, yes. We put the AI presenter over real footage of your product, and that\\u2019s a big part of why it\\n                feels believable. It won\\u2019t suit every brand though, so we\\u2019d suggest testing AI UGC vs real creator UGC\\n                side by side.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we translate our existing winning UGC videos into other languages?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. We can re-voice and lip-sync a video that\\u2019s already working. Right now that means Hindi, Tamil,\\n                Telugu and English.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How quickly can you deliver an AI UGC video batch?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"New versions can be ready in 48 to 72 hours. A bigger batch will take a bit longer, and we\\u2019ll share the\\n                AI UGC video turnaround dates when you send the brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Are AI personas cleared for commercial advertising?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"You get commercial ad rights with every video, and the details are in your agreement. Please read it\\n                before you sign. [CONFIRM: wording on AI presenter licensing]\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Which products suit AI UGC videos best?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Products that are easy to show up close and easy to explain in 15 to 45 seconds. If your product needs a\\n                long demo or a lot of explaining, a real creator video usually works better.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do I need to label AI-made ads on Meta and TikTok?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Platform rules on AI labels can change, so check the latest policy before you upload. We\\u2019ll flag it in\\n                your brief and help you set it up. [CONFIRM]\"\n            }\n        }\n    ]\n}','published','2026-11-05 15:33:54','2026-11-13 14:14:39'),
