(42,'service-ugc-product-video-company','Ugc Product Video Service','Ugc Product Video Service FAQPage Schema','FAQPage','{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-product-video-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Which products are best suited to UGC product videos?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Any products that your customers would want to see before purchasing. Beauty, Skincare, Kitchenware,\\n                Homeware & Clothing all do well as they have texture and finish.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Is this suitable for all products?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"No. If your product requires a long technical video or customers don\'t care about it looking nice up\\n                close then a creator video won\'t help much. We\'ll let you know before you pay.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we request certain features to be shown?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes! We\'ll include these in your brief. They will be added to your script and shot list. You\'ll approve\\n                these.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Will we receive raw footage?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes! We\'ll include this if requested. Just mention this in your brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we use these on our Shopify product page?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes! They\'re regular MP4s so you can upload them.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How many samples should we send?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Typically one per creator. If your product runs out whilst filming then send an extra.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How long will it take?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually 7-12 working days from brief to final files. If samples arrive late or we have slow feedback\\n                this can be longer.\"\n            }\n        }\n    ]\n}','published','2026-11-05 15:33:54','2026-11-13 14:14:39'),
