(58,'service-ugc-video-creation-services-company','Ugc Video Creation Services Service','Ugc Video Creation Services Service FAQPage Schema','FAQPage','{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-video-creation-services-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is included in UGC video creation services?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"We find the creator, write the script, manage the shoot and edit the video. You get final files with\\n                captions, in the sizes you need.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How do you choose and vet creators for our brand?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"We start from your product and your buyers. Then we shortlist creators whose style and past videos\\n                seem like a good fit. If you want to hire UGC creators from a specific niche or city, tell us in the\\n                brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can our team review and approve scripts before filming starts?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Nobody films until you\\u2019ve approved the script.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What commercial usage rights are included with the videos?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"You can use them in your ads and marketing. The platforms and the duration are written in your\\n                agreement, so please read it before you sign.\"\n            }\